1  import {useFocusEffect} from '@react-navigation/native';
     2  import React, {useCallback, useEffect, useMemo, useRef} from 'react';
     3  import type {OnyxEntry} from 'react-native-onyx';
     4  import {useOnyx, withOnyx} from 'react-native-onyx';
     5  import type {BaseTextInputRef} from '@components/TextInput/BaseTextInput/types';
     6  import withCurrentUserPersonalDetails from '@components/withCurrentUserPersonalDetails';
     7  import type {WithCurrentUserPersonalDetailsProps} from '@components/withCurrentUserPersonalDetails';
     8  import useLocalize from '@hooks/useLocalize';
     9  import * as TransactionEdit from '@libs/actions/TransactionEdit';
    10  import * as CurrencyUtils from '@libs/CurrencyUtils';
    11  import Navigation from '@libs/Navigation/Navigation';
    12  import * as OptionsListUtils from '@libs/OptionsListUtils';
    13  import * as ReportUtils from '@libs/ReportUtils';
    14  import * as TransactionUtils from '@libs/TransactionUtils';
    15  import {getRequestType} from '@libs/TransactionUtils';
    16  import MoneyRequestAmountForm from '@pages/iou/MoneyRequestAmountForm';
    17  import * as IOU from '@userActions/IOU';
    18  import CONST from '@src/CONST';
    19  import ONYXKEYS from '@src/ONYXKEYS';
    20  import ROUTES from '@src/ROUTES';
    21  import type SCREENS from '@src/SCREENS';
    22  import type * as OnyxTypes from '@src/types/onyx';
    23  import type {PaymentMethodType} from '@src/types/onyx/OriginalMessage';
    24  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    25  import StepScreenWrapper from './StepScreenWrapper';
    26  import withFullTransactionOrNotFound from './withFullTransactionOrNotFound';
    27  import type {WithWritableReportOrNotFoundProps} from './withWritableReportOrNotFound';
    28  import withWritableReportOrNotFound from './withWritableReportOrNotFound';
    29
    30  type AmountParams = {
    31      amount: string;
    32      paymentMethod?: PaymentMethodType;
    33  };
    34
    35  type IOURequestStepAmountOnyxProps = {
    36      /** The draft transaction that holds data to be persisted on the current transaction */
    37      splitDraftTransaction: OnyxEntry<OnyxTypes.Transaction>;
    38
    39      /** Whether the confirmation step should be skipped */
    40      skipConfirmation: OnyxEntry<boolean>;
    41
    42      /** The draft transaction object being modified in Onyx */
    43      draftTransaction: OnyxEntry<OnyxTypes.Transaction>;
    44
    45      /** Personal details of all users */
    46      personalDetails: OnyxEntry<OnyxTypes.PersonalDetailsList>;
    47
    48      /** The policy which the user has access to and which the report is tied to */
    49      policy: OnyxEntry<OnyxTypes.Policy>;
    50  };
    51
    52  type IOURequestStepAmountProps = IOURequestStepAmountOnyxProps &
    53      WithCurrentUserPersonalDetailsProps &
    54      WithWritableReportOrNotFoundProps<typeof SCREENS.MONEY_REQUEST.STEP_AMOUNT | typeof SCREENS.MONEY_REQUEST.CREATE> & {
    55          /** The transaction object being modified in Onyx */
    56          transaction: OnyxEntry<OnyxTypes.Transaction>;
    57
    58          /** Whether the user input should be kept or not */
    59          shouldKeepUserInput?: boolean;
    60      };
    61
    62  function IOURequestStepAmount({
    63      report,
    64      route: {
    65          params: {iouType, reportID, transactionID, backTo, pageIndex, action, currency: selectedCurrency = ''},
    66      },
    67      transaction,
    68      policy,
    69      personalDetails,
    70      currentUserPersonalDetails,
    71      splitDraftTransaction,
    72      skipConfirmation,
    73      draftTransaction,
    74      shouldKeepUserInput = false,
    75  }: IOURequestStepAmountProps) {
    76      const {translate} = useLocalize();
    77      const textInput = useRef<BaseTextInputRef | null>(null);
    78      const focusTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    79      const isSaveButtonPressed = useRef(false);
    80      const iouRequestType = getRequestType(transaction);
    81      const [reportNameValuePairs] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${report?.reportID ?? -1}`);
    82
    83      const isEditing = action === CONST.IOU.ACTION.EDIT;
    84      const isSplitBill = iouType === CONST.IOU.TYPE.SPLIT;
    85      const isEditingSplitBill = isEditing && isSplitBill;
    86      const currentTransaction = isEditingSplitBill && !isEmptyObject(splitDraftTransaction) ? splitDraftTransaction : transaction;
    87      const {amount: transactionAmount} = ReportUtils.getTransactionDetails(currentTransaction) ?? {amount: 0};
    88      const {currency: originalCurrency} = ReportUtils.getTransactionDetails(isEditing ? draftTransaction : transaction) ?? {currency: CONST.CURRENCY.USD};
    89      const currency = CurrencyUtils.isValidCurrencyCode(selectedCurrency) ? selectedCurrency : originalCurrency;
    90
    91      // For quick button actions, we'll skip the confirmation page unless the report is archived or this is a workspace request, as
    92      // the user will have to add a merchant.
    93      const shouldSkipConfirmation: boolean = useMemo(() => {
    94          if (!skipConfirmation || !report?.reportID) {
    95              return false;
    96          }
    97
    98          return !(ReportUtils.isArchivedRoom(report, reportNameValuePairs) || ReportUtils.isPolicyExpenseChat(report));
    99      }, [report, skipConfirmation, reportNameValuePairs]);
   100
   101      useFocusEffect(
   102          useCallback(() => {
   103              focusTimeoutRef.current = setTimeout(() => textInput.current?.focus(), CONST.ANIMATED_TRANSITION);
   104              return () => {
   105                  if (!focusTimeoutRef.current) {
   106                      return;
   107                  }
   108                  clearTimeout(focusTimeoutRef.current);
   109              };
   110          }, []),
   111      );
   112
   113      useEffect(() => {
   114          if (!isEditing) {
   115              return;
   116          }
   117          // A temporary solution to not prevent users from editing the currency
   118          // We create a backup transaction and use it to save the currency and remove this transaction backup if we don't save the amount
   119          // It should be removed after this issue https://github.com/Expensify/App/issues/34607 is fixed
   120          TransactionEdit.createDraftTransaction(isEditingSplitBill && !isEmptyObject(splitDraftTransaction) ? splitDraftTransaction : transaction);
   121
   122          return () => {
   123              if (isSaveButtonPressed.current) {
   124                  return;
   125              }
   126              TransactionEdit.removeDraftTransaction(transaction?.transactionID ?? '-1');
   127          };
   128          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   129      }, []);
   130
   131      const navigateBack = () => {
   132          Navigation.goBack(backTo);
   133      };
   134
   135      const navigateToCurrencySelectionPage = () => {
   136          Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CURRENCY.getRoute(action, iouType, transactionID, reportID, pageIndex, currency, Navigation.getActiveRoute()));
   137      };
   138
   139      const navigateToParticipantPage = () => {
   140          switch (iouType) {
   141              case CONST.IOU.TYPE.REQUEST:
   142                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(CONST.IOU.TYPE.SUBMIT, transactionID, reportID));
   143                  break;
   144              case CONST.IOU.TYPE.SEND:
   145                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(CONST.IOU.TYPE.PAY, transactionID, reportID));
   146                  break;
   147              default:
   148                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_PARTICIPANTS.getRoute(iouType, transactionID, reportID));
   149          }
   150      };
   151
   152      const navigateToConfirmationPage = () => {
   153          switch (iouType) {
   154              case CONST.IOU.TYPE.REQUEST:
   155                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.SUBMIT, transactionID, reportID));
   156                  break;
   157              case CONST.IOU.TYPE.SEND:
   158                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.PAY, transactionID, reportID));
   159                  break;
   160              default:
   161                  Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, iouType, transactionID, reportID));
   162          }
   163      };
   164
   165      const navigateToNextPage = ({amount, paymentMethod}: AmountParams) => {
   166          isSaveButtonPressed.current = true;
   167          const amountInSmallestCurrencyUnits = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   168
   169          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   170          IOU.setMoneyRequestAmount(transactionID, amountInSmallestCurrencyUnits, currency || CONST.CURRENCY.USD, shouldKeepUserInput);
   171
   172          // Initially when we're creating money request, we do not know the participant and hence if the request is with workspace with tax tracking enabled
   173          // So, we reset the taxAmount here and calculate it in the hook in MoneyRequestConfirmationList component
   174          IOU.setMoneyRequestTaxAmount(transactionID, null);
   175
   176          if (backTo) {
   177              Navigation.goBack(backTo);
   178              return;
   179          }
   180
   181          // If a reportID exists in the report object, it's because either:
   182          // - The user started this flow from using the + button in the composer inside a report.
   183          // - The user started this flow from using the global create menu by selecting the Track expense option.
   184          // In this case, the participants can be automatically assigned from the report and the user can skip the participants step and go straight
   185          // to the confirm step.
   186          // If the user is started this flow using the Create expense option (combined submit/track flow), they should be redirected to the participants page.
   187          if (report?.reportID && !ReportUtils.isArchivedRoom(report, reportNameValuePairs) && iouType !== CONST.IOU.TYPE.CREATE) {
   188              const selectedParticipants = IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   189              const participants = selectedParticipants.map((participant) => {
   190                  const participantAccountID = participant?.accountID ?? -1;
   191                  return participantAccountID ? OptionsListUtils.getParticipantsOption(participant, personalDetails) : OptionsListUtils.getReportOption(participant);
   192              });
   193              const backendAmount = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   194
   195              if (shouldSkipConfirmation) {
   196                  // Only skip confirmation when the split is not configurable, for now Smartscanned splits cannot be configured
   197                  if (iouType === CONST.IOU.TYPE.SPLIT && transaction?.iouRequestType === CONST.IOU.REQUEST_TYPE.SCAN) {
   198                      IOU.splitBill({
   199                          participants,
   200                          currentUserLogin: currentUserPersonalDetails.login ?? '',
   201                          currentUserAccountID: currentUserPersonalDetails.accountID,
   202                          amount: backendAmount,
   203                          comment: '',
   204                          currency,
   205                          merchant: CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   206                          tag: '',
   207                          category: '',
   208                          created: transaction?.created ?? '',
   209                          billable: false,
   210                          iouRequestType: CONST.IOU.REQUEST_TYPE.MANUAL,
   211                          existingSplitChatReportID: report?.reportID,
   212                      });
   213                      return;
   214                  }
   215
   216                  if (iouType === CONST.IOU.TYPE.PAY || iouType === CONST.IOU.TYPE.SEND) {
   217                      if (paymentMethod && paymentMethod === CONST.IOU.PAYMENT_TYPE.EXPENSIFY) {
   218                          IOU.sendMoneyWithWallet(report, backendAmount, currency, '', currentUserPersonalDetails.accountID, participants.at(0) ?? {});
   219                          return;
   220                      }
   221
   222                      IOU.sendMoneyElsewhere(report, backendAmount, currency, '', currentUserPersonalDetails.accountID, participants.at(0) ?? {});
   223                      return;
   224                  }
   225                  if (iouType === CONST.IOU.TYPE.SUBMIT || iouType === CONST.IOU.TYPE.REQUEST) {
   226                      IOU.requestMoney(
   227                          report,
   228                          backendAmount,
   229                          transaction?.attendees,
   230                          currency,
   231                          transaction?.created ?? '',
   232                          CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   233                          currentUserPersonalDetails.login,
   234                          currentUserPersonalDetails.accountID,
   235                          participants.at(0) ?? {},
   236                          '',
   237                          {},
   238                      );
   239                      return;
   240                  }
   241                  if (iouType === CONST.IOU.TYPE.TRACK) {
   242                      IOU.trackExpense(
   243                          report,
   244                          backendAmount,
   245                          currency ?? 'USD',
   246                          transaction?.created ?? '',
   247                          CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   248                          currentUserPersonalDetails.login,
   249                          currentUserPersonalDetails.accountID,
   250                          participants.at(0) ?? {},
   251                          '',
   252                      );
   253                      return;
   254                  }
   255              }
   256              IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   257              if (isSplitBill && !report.isOwnPolicyExpenseChat && report.participants) {
   258                  const participantAccountIDs = Object.keys(report.participants).map((accountID) => Number(accountID));
   259                  IOU.setSplitShares(transaction, amountInSmallestCurrencyUnits, currency || CONST.CURRENCY.USD, participantAccountIDs);
   260              }
   261              navigateToConfirmationPage();
   262              return;
   263          }
   264
   265          // If there was no reportID, then that means the user started this flow from the global + menu
   266          // and an optimistic reportID was generated. In that case, the next step is to select the participants for this expense.
   267          navigateToParticipantPage();
   268      };
   269
   270      const saveAmountAndCurrency = ({amount, paymentMethod}: AmountParams) => {
   271          const newAmount = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   272
   273          // Edits to the amount from the splits page should reset the split shares.
   274          if (transaction?.splitShares) {
   275              IOU.resetSplitShares(transaction, newAmount, currency);
   276          }
   277
   278          if (!isEditing) {
   279              navigateToNextPage({amount, paymentMethod});
   280              return;
   281          }
   282
   283          // If the value hasn't changed, don't request to save changes on the server and just close the modal
   284          const transactionCurrency = TransactionUtils.getCurrency(currentTransaction);
   285          if (newAmount === TransactionUtils.getAmount(currentTransaction) && currency === transactionCurrency) {
   286              navigateBack();
   287              return;
   288          }
   289
   290          // If currency has changed, then we get the default tax rate based on currency, otherwise we use the current tax rate selected in transaction, if we have it.
   291          const transactionTaxCode = ReportUtils.getTransactionDetails(currentTransaction)?.taxCode;
   292          const defaultTaxCode = TransactionUtils.getDefaultTaxCode(policy, currentTransaction, currency) ?? '';
   293          const taxCode = (currency !== transactionCurrency ? defaultTaxCode : transactionTaxCode) ?? defaultTaxCode;
   294          const taxPercentage = TransactionUtils.getTaxValue(policy, currentTransaction, taxCode) ?? '';
   295          const taxAmount = CurrencyUtils.convertToBackendAmount(TransactionUtils.calculateTaxAmount(taxPercentage, newAmount, currency ?? CONST.CURRENCY.USD));
   296
   297          if (isSplitBill) {
   298              IOU.setDraftSplitTransaction(transactionID, {amount: newAmount, currency, taxCode, taxAmount});
   299              navigateBack();
   300              return;
   301          }
   302
   303          IOU.updateMoneyRequestAmountAndCurrency({transactionID, transactionThreadReportID: reportID, currency, amount: newAmount, taxAmount, policy, taxCode});
   304          navigateBack();
   305      };
   306
   307      return (
   308          <StepScreenWrapper
   309              headerTitle={translate('iou.amount')}
   310              onBackButtonPress={navigateBack}
   311              testID={IOURequestStepAmount.displayName}
   312              shouldShowWrapper={!!backTo || isEditing}
   313              includeSafeAreaPaddingBottom
   314          >
   315              <MoneyRequestAmountForm
   316                  isEditing={!!backTo || isEditing}
   317                  currency={currency}
   318                  amount={Math.abs(transactionAmount)}
   319                  skipConfirmation={shouldSkipConfirmation ?? false}
   320                  iouType={iouType}
   321                  policyID={policy?.id ?? '-1'}
   322                  bankAccountRoute={ReportUtils.getBankAccountRoute(report)}
   323                  ref={(e) => (textInput.current = e)}
   324                  shouldKeepUserInput={transaction?.shouldShowOriginalAmount}
   325                  onCurrencyButtonPress={navigateToCurrencySelectionPage}
   326                  onSubmitButtonPress={saveAmountAndCurrency}
   327                  selectedTab={iouRequestType}
   328              />
   329          </StepScreenWrapper>
   330      );
   331  }
   332
   333  IOURequestStepAmount.displayName = 'IOURequestStepAmount';
   334
   335  const IOURequestStepAmountWithOnyx = withOnyx<IOURequestStepAmountProps, IOURequestStepAmountOnyxProps>({
   336      splitDraftTransaction: {
